#topMenu {
  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
  z-index: 9200; display: flex; flex-direction: column; align-items: center;
}
/* Reading mode owns the top edge (#readingModeHeaderEl is sticky top:0) — get out of its way entirely. */
body.reading-mode-on #topMenu { display: none; }
#topMenuBar {
  display: flex; flex-direction: row; align-items: center; gap: 1px;
  background: var(--remote-bg, rgba(22,22,22,0.90));
  border-radius: 0 0 8px 8px;
  padding: 3px 5px;
  backdrop-filter: blur(6px);
  border: 1px solid var(--remote-border, rgba(255,255,255,0.10));
  border-top: none;
  max-width: 96vw; flex-wrap: wrap; justify-content: center;
}
#topMenu.remote-collapsed #topMenuBar { display: none; }
/* .remote-separator is a horizontal rule in the vertical remotes — turn it on its side here. */
#topMenuBar .remote-separator { width: 1px; height: 16px; margin: 0 3px; }
#topMenuToggleTab {
  background: var(--remote-bg, rgba(22,22,22,0.90));
  border: 1px solid var(--remote-border, rgba(255,255,255,0.10));
  border-top: none;
  border-radius: 0 0 6px 6px;
  padding: 2px 14px; cursor: pointer; font-size: 70%;
  color: var(--remote-text, #bbb); line-height: 1;
  backdrop-filter: blur(6px); user-select: none; transition: color .15s;
}
#topMenuToggleTab:hover { color: var(--remote-text-hover, #fff); }
/* Tooltip override: the global bubble sits ABOVE its host (bottom: 100% + 7px), which is off-screen for a
   bar glued to the top edge — flip it below, mirroring what #quickRemote does for the left/right edges. */
#topMenu [data-tooltip]::after {
  bottom: auto; top: calc(100% + 7px);
  left: 50%; right: auto; transform: translateX(-50%);
  white-space: nowrap; max-width: 200px; text-align: center;
}

