/* ── Design tokens (2026-08, repolish funky) — compose AVEC les variables de thème Perchance
   (--app-bg/--box-color/--box-border-color/--text-color, injectées par la plateforme, non
   redéfinies ici), ne les remplace pas. --accent-1/--accent-2 reprennent le violet/ambre déjà
   utilisés ailleurs dans ce fichier (glow du titre, accents divers) ; --accent-3/--accent-4 sont
   nouveaux (magenta/cyan) pour un peu plus de vie sur les états secondaires. ── */
:root, body {
  --accent-1: #8b5cf6;
  --accent-1-soft: rgba(139,92,246,0.15);
  --accent-2: #cb6900;
  --accent-3: #ec4899;
  --accent-4: #22d3ee;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --shadow-card: 0 6px 20px rgba(0,0,0,0.35);
  --shadow-modal: 0 10px 34px rgba(0,0,0,0.55);
  --glow-accent: 0 0 0 3px var(--accent-1-soft);
  --ease-snap: cubic-bezier(.2,.8,.2,1);
}
/* ── Reading mode ── */
#storyReadingViewEl {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1000;
  overflow-y: auto;
  background: var(--app-bg, #f5f5f0);
  box-sizing: border-box;
  scrollbar-gutter: stable;
}
#readingModeHeaderEl {
  position: sticky;
  top: 0;
  z-index: 1001;
  background: var(--app-bg, #f5f5f0);
  border-bottom: 1px solid var(--box-border-color, #888);
  padding: 0.4rem 0.8rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}
#readingModeContentEl {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1.2rem 4rem;
  line-height: 1.75;
  font-size: calc(1rem * var(--story-font-scale, 1));
  color: var(--text-color, inherit);
  position: relative; /* sit above the faint #readingModeBgEl background layer */
  z-index: 1;
}
#readingModeContentEl p {
  margin: 0 0 1em 0;
}
#readingModeContentEl .summary-block {
  font-size: 80%;
  opacity: 0.5;
  font-style: italic;
  border-left: 2px solid currentColor;
  padding-left: 0.6rem;
  margin: 0 0 1em 0;
}
.reading-illus-block {
  margin: 1.5rem auto;
  text-align: center;
  max-width: 680px;
}
.reading-illus-block img {
  max-width: 100%;
  border-radius: 5px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.25);
  display: block;
  margin: 0 auto;
}
.reading-illus-caption {
  font-size: 73%;
  opacity: 0.55;
  margin-top: 0.4rem;
  font-style: italic;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}
#readingModeBtn {
  margin-left: 0.5rem;
  font-size: 90%;
  padding: 0 0.5rem;
}
.chapter-heading {
  text-align: center;
  margin: 2.5rem 0 1.2rem;
  font-size: 115%;
  font-weight: bold;
  opacity: 0.85;
  border-bottom: 1px solid currentColor;
  padding-bottom: 0.5rem;
}
.illustration-download-btn {
  font-size: 70%;
  margin-right: 0.25rem;
  text-decoration: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
}

#trackingTabsCtn {
  width: 100%;
  margin-top: 0.5rem;
  border: 1px solid var(--box-border-color, #888);
  border-radius: 4px;
  background-color: var(--box-color, #f9f9f9);
}
#tabButtons {
  display: flex;
  flex-wrap: wrap; /* Allow tabs to wrap on small screens */
  border-bottom: 1px solid var(--box-border-color, #888);
}
.tab-btn {
  padding: 8px 12px;
  cursor: pointer;
  background-color: transparent;
  border: none;
  border-bottom: 1px solid var(--box-border-color, #888); /* Add bottom border for inactive */
  opacity: 0.7;
  font-size: 85%;
  color: var(--tab-text-color, #000); /* Use variable for text color */
}
/* Remove right border, use bottom border for separation */
.tab-btn:last-child {
  border-right: none;
}
.tab-btn.active {
  background-color: var(--tab-active-bg, #fff); /* Use variable for active BG */
  opacity: 1;
  border-bottom: 1px solid var(--tab-active-bg, #fff); /* Hide bottom border */
  margin-bottom: -1px; /* Pulls the tab content up */
  font-weight: bold;
}
.tab-content {
  display: none;
  padding: 8px;
}
.tab-content.active {
  display: block;
}
.tab-content textarea {
  width: 100%;
  min-height: 100px;
  resize: vertical;
}
/* Style for the generate button row in each tab */
.tab-generate-bar {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  padding: 4px;
}
.tab-generate-bar button {
  font-size: 80%;
  padding: 4px 8px;
}
.tab-loader {
  font-size: 80%;
  display: none; /* Hide loader by default */
}

/* ── Tooltip system ── */
[data-tooltip] { position: relative; }
/* Règle user (2026-07-02) : une tooltip s'affiche TOUJOURS au-dessus des autres éléments. Le z-index du
   ::after ne suffit pas quand un panneau VOISIN recouvre l'hôte : on élève aussi l'hôte survolé lui-même
   (il est positionné → le z-index prend), au maximum 32 bits sur la bulle.
   2026-07-23 (user) : plafonné à 500 — le :hover reste collé après un tap (mobile) ou tant que la souris
   ne bouge pas (desktop), donc un hôte élevé au max restait en surimpression SUR les popups qui venaient
   de s'ouvrir. 500 > tous les panneaux de contenu (z-index ≤ 10) mais < mode lecture (1000), barres
   remote (9200) et toutes les modales (≥ 9998). */
[data-tooltip]:hover { z-index: 500; }
[data-tooltip]::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: calc(100% + 7px);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(10,10,10,0.93);
  color: #efefef;
  padding: 5px 10px;
  border-radius: 5px;
  font-size: 71%;
  font-style: normal;
  font-weight: normal;
  pointer-events: none;
  opacity: 0;
  z-index: 2147483647;
  max-width: 230px;
  white-space: normal;
  text-align: center;
  box-shadow: 0 4px 16px rgba(0,0,0,0.5);
  line-height: 1.4;
  border: 1px solid rgba(255,255,255,0.08);
}
[data-tooltip]:hover::after { animation: tipShow 0.18s ease 1.5s forwards; }
@keyframes tipShow { to { opacity: 1; } }

/* ── Token budget breakdown popup (2026-07-27) ──
   Rich floating panel for #tokenBudgetBadge — the plain data-tooltip can only show flat text, this shows a
   sorted, bar-charted list of every measured piece so the author can see what to trim. Same "always on top"
   rule as the tooltip system above (feedback_tooltips_always_on_top): fixed position, max z-index.
   Two presentations share the .tbd-panel content styling: #tokenBudgetDetailPopup (hover, anchored near the
   badge, desktop quick-glance) and #tokenBudgetDetailModal (click/tap, centered — 2026-07-27 addition, more
   usable on mobile where hover doesn't exist and a small anchored box is fiddly to read/scroll). */
#tokenBudgetDetailPopup {
  position: fixed;
  z-index: 2147483647;
  background: rgba(10,10,10,0.96);
  color: #efefef;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 6px;
  box-shadow: 0 6px 20px rgba(0,0,0,0.55);
  padding: 8px 10px;
  font-size: 0.72rem;
  line-height: 1.35;
  width: 280px;
  max-width: 90vw;
  max-height: 70vh;
  overflow-y: auto;
  pointer-events: none;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.12s ease, transform 0.12s ease;
}
#tokenBudgetDetailPopup.tbd-open { opacity: 1; transform: translateY(0); }
.tbd-panel .tbd-title { font-weight: bold; margin-bottom: 4px; opacity: 0.9; }
.tbd-panel .tbd-summary { margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.15); opacity: 0.85; }
.tbd-panel .tbd-row { position: relative; margin: 2px 0; padding: 2px 4px; border-radius: 3px; overflow: hidden; }
.tbd-panel .tbd-bar { position: absolute; left: 0; top: 0; bottom: 0; background: rgba(140,100,220,0.28); border-radius: 3px; z-index: 0; }
.tbd-panel .tbd-fixed .tbd-bar { background: rgba(150,150,150,0.22); }
.tbd-panel .tbd-label { position: relative; z-index: 1; display: flex; justify-content: space-between; gap: 6px; }
.tbd-panel .tbd-val { font-family: monospace; opacity: 0.9; white-space: nowrap; }
.tbd-panel .tbd-note { margin-top: 6px; opacity: 0.6; font-style: italic; }

#tokenBudgetDetailBackdrop {
  position: fixed; inset: 0;
  z-index: 2147483646;
  background: rgba(0,0,0,0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease;
}
#tokenBudgetDetailBackdrop.tbd-modal-open { opacity: 1; pointer-events: auto; }
#tokenBudgetDetailModal {
  position: fixed;
  z-index: 2147483647;
  left: 50%; top: 50%;
  transform: translate(-50%, -46%);
  background: rgba(10,10,10,0.97);
  color: #efefef;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 8px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.6);
  padding: 14px 16px 10px;
  font-size: 0.8rem;
  line-height: 1.4;
  width: 320px;
  max-width: 92vw;
  max-height: 80vh;
  overflow-y: auto;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
}
#tokenBudgetDetailModal.tbd-modal-open { opacity: 1; transform: translate(-50%, -50%); pointer-events: auto; }
#tokenBudgetDetailModal .tbd-modal-close {
  position: absolute; top: 6px; right: 10px;
  cursor: pointer; opacity: 0.65; font-size: 1.1rem; line-height: 1; padding: 4px;
}
#tokenBudgetDetailModal .tbd-modal-close:hover { opacity: 1; }

/* 🩺 AI health badge (2026-08-30) — mêmes règles .tbd-panel, ids sœurs (additif, ne touche pas au CSS
   partagé ci-dessus) */
#aiHealthDetailPopup {
