#aiHealthDetailModal.tbd-modal-open { opacity: 1; transform: translate(-50%, -50%); pointer-events: auto; }
#aiHealthDetailModal .tbd-modal-close {
  position: absolute; top: 6px; right: 10px;
  cursor: pointer; opacity: 0.65; font-size: 1.1rem; line-height: 1; padding: 4px;
}
#aiHealthDetailModal .tbd-modal-close:hover { opacity: 1; }

/* 2026-07-05 (user): the tracker / subtext / dynamics panels used overflow:hidden purely to clip their
   rounded corners — but that ALSO clipped the upward-popping tooltips of their header 🔄/🗑️ buttons
   (a position:absolute ::after can't escape an overflow:hidden ancestor, so the 07-02 z-index rule was
   powerless there). overflow is now visible on those three panels; the corners stay clean by rounding the
   header (first child) and last child instead of relying on the parent clip. */
#recentStoryPanelEl > *:first-child,
#subtextPanelEl    > *:first-child,
#dynamicsPanelEl   > *:first-child { border-radius: 4px 4px 0 0; }
#recentStoryPanelEl > *:last-child,
#subtextPanelEl    > *:last-child,
#dynamicsPanelEl   > *:last-child  { border-radius: 0 0 4px 4px; }

/* ── Page title ── */
#topStuffEl {
  width: 100%;
  text-align: center;
  padding-bottom: 0.6rem;
  margin-bottom: 0.5rem;
  position: relative;
}
#topStuffEl::after {
  content: '';
  display: block;
  height: 2px;
  width: 65%;
  margin: 0.6rem auto 0;
  /* Fallback only kicks in if the platform hasn't injected --box-border-color — same look in prod
     as before, but a tri-tone violet→magenta gradient instead of plain amber if it ever doesn't. */
  background: linear-gradient(90deg, transparent, var(--box-border-color, linear-gradient(90deg, var(--accent-1, #8b5cf6), var(--accent-3, #ec4899))), transparent);
  border-radius: 2px;
}
#topStuffEl h1 { font-size: 180% !important; font-weight: 800; letter-spacing: -0.01em; margin-bottom: 0.15rem; }

/* ── Main wrapper subtle ambient glow ── */
#mainWrapperEl {
  background:
    radial-gradient(ellipse 90% 28% at 50% 0%,  rgba(140,80,220,0.075) 0%, transparent 100%),
    radial-gradient(ellipse 65% 22% at 85% 100%, rgba(40,100,210,0.045) 0%, transparent 100%),
    radial-gradient(ellipse 55% 20% at 15% 100%, rgba(236,72,153,0.03) 0%, transparent 100%);
  border-radius: 10px;
  padding-top: 0.2rem;
}

/* ── Character panel toggle button ── */
#charAppearancesToggleBtn {
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: filter 0.15s;
  padding: 6px 10px;
}
#charAppearancesToggleBtn:hover { filter: brightness(1.1); }

/* ── Illustration caption reveal animation ── */
.illustration-caption:not([hidden]) {
  animation: captionReveal 0.22s ease;
}
@keyframes captionReveal {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 0.65; transform: translateY(0); }
}

/* ── Character cards — mobile layout (class set by JS via window.innerWidth) ── */
.char-mobile .char-body {
  flex-wrap: wrap !important;
}
.char-mobile .char-portrait-area {
  flex: 0 0 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  flex-direction: row !important;
  justify-content: center !important;
  align-items: flex-start !important;
  gap: 16px !important;
  border-right: none !important;
  border-bottom: 1px solid var(--box-border-color, #888) !important;
  padding: 6px 8px !important;
}
.char-mobile .char-portrait-sep {
  display: none !important;
}
.char-mobile .char-fields-grid {
  flex: 0 0 100% !important;
  min-width: 0 !important;
  grid-template-columns: 1fr !important;
}
.char-mobile .char-quarter-row > * {
  flex-basis: calc(25% - 5px) !important; /* ¼ fields stay a TRUE quarter (four per row) on narrow cards too (2026-07-05, user: "un quart, pas 1/2") — matches the desktop inline flex-basis */
}
/* 📊 Gauge (current/max bar) needs horizontal room its buttons+input+max label won't give at ¼ width on a narrow
   card → the widgets overflow and overlap between neighbouring gauges. Force each gauge onto its own full-width row
   on mobile. The first selector outranks the ¼ rule above (three classes vs two); the second covers grid blocks. */
.char-mobile .char-quarter-row > .char-gauge-block,
.char-mobile .char-gauge-block {
  flex: 1 1 100% !important;
  flex-basis: 100% !important;
  width: 100% !important;
  grid-column: 1 / -1 !important;
}
.char-mobile .char-outfits-col,
.char-mobile .char-personas-col {
  flex: 0 0 100% !important;
  width: 100% !important;
  flex-direction: row !important;
  flex-wrap: wrap !important;
  border-left: none !important;
  border-top: 1px solid var(--box-border-color, #888) !important;
  padding: 3px 4px 4px !important;
  gap: 2px !important;
}
.char-mobile .char-outfit-hdr,
.char-mobile .char-persona-hdr {
  flex: 0 0 100% !important;
  width: 100% !important;
  margin-bottom: 2px !important;
}
.char-mobile .char-outfit-row,
.char-mobile .char-persona-row {
  flex: 0 0 auto !important; /* chip auto-sized to its own content (≈ width of the 3 buttons below), several fit per line */
  width: auto !important;
  flex-direction: column !important;
  align-items: stretch !important;
  padding: 2px 3px !important;
  gap: 1px !important;
}
.char-mobile .char-op-row-top {
  display: flex !important;
  align-items: center !important;
  gap: 2px !important;
}
.char-mobile .char-op-row-btns {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 2px !important;
}
.char-mobile .char-outfit-name,
.char-mobile .char-persona-name {
  flex: 1 1 0 !important; /* stretched to the row's own width (set by the buttons line), never wider → truncates instead of forcing the chip wide */
  width: 0 !important;
  min-width: 0 !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}
/* 🔒 Per-field AI lock (2026-07-23, user) — hidden by default; every badge appears while the card's
   🪄 Enhance/Modify panel is open (.ai-lock-edit on the card root); a locked field keeps a quiet 🔒
   visible at all times as a glance cue. */
.ai-lock-badge { display:none; font-size:72%; line-height:1; padding:0 2px; background:none; border:none; cursor:pointer; opacity:0.45; flex-shrink:0; }
.ai-lock-badge.ai-locked { display:inline-block; opacity:0.8; }
.ai-lock-edit .ai-lock-badge { display:inline-block; }
.ai-lock-edit .ai-lock-badge:hover { opacity:1; }

css3:
#storySoFarDeleteBtn[data-mode='delete']:before { content:'🗑️ delete'; }
#storySoFarDeleteBtn[data-mode='undo']:before { content:'↩️ undo'; }

/* 📏 Story font size (2026-07-15, user). Set on the editor root rather than on its inner layers:
   createTextEditor paints markdown / dialogue colours with <span style> children, so the size has to
   inherit down to every layer at once or the text and its colour overlay drift apart. The textStyleRules
   are all em-relative (the *** markers sit at 0.55em) so they follow this scale on their own. */
#storySoFarEl { font-size: calc(1rem * var(--story-font-scale, 1)); }

css4:
/* Text-only mode (🖼️ Images unchecked) — hide every image-related surface. Inline display
   styles on some of these are overridden with !important. The universe ambient background is
   also stopped programmatically in setImageGenDisabled (this just hides any leftover div). */
body.image-gen-off #illustrationControlsBox,
body.image-gen-off #illustrationOuterEl,
body.image-gen-off #universeBackgroundDiv,
body.image-gen-off [data-portraittoggle],
body.image-gen-off .card-collapsed-illus,
body.image-gen-off .char-portrait-area { display: none !important; }

/* Scene-art-only off (🚫 Scene art, 2026-07-11) — hide ONLY the story scene-illustration
   surfaces (controls box + gallery). Character portraits and the universe ambient background
   are deliberately left alone. Scene entry points also bail via SCENE_ILLUS_DISABLED. */
body.scene-illus-off #illustrationControlsBox,
body.scene-illus-off #illustrationOuterEl { display: none !important; }

/* No-Markdown mode — neutralize the inline styles the text-editor applies via textStyleRules
   so dialogues / bold / italic render as plain text. Markers like *** become visible. */
body.no-md-mode #storySoFarEl span[style],
body.no-md-mode #storyOverviewEl span[style] {
  font-weight: inherit !important;
  font-style: inherit !important;
  font-size: inherit !important;
  letter-spacing: inherit !important;
  color: inherit !important;
}

